    ['<b>Creamy sections corner benefits</b>', 'need <b>better targeting, not abolition</b>; poor targeting afflicts many schemes'],
    ['<b>Mismatch hypothesis</b>', 'dropout needs <b>evidence</b>, not generalising; answer is <b>extra and remedial classes, counselling</b>'],
